-- Background details for the Tracks tab, researched from Wikipedia, Forza.net and GTPlanet. Matches venues by name; safe to re-run.

update public.track_venues set kind = 'real', based_on = null, opened_year = 1950, history = 'Brands Hatch is in West Kingsdown, Kent. Racing began there in 1926 on a grass track, and the tarmac car circuit opened on 16 April 1950; it hosted the British Grand Prix in alternate years from 1964 to 1986.', source_url = 'https://en.wikipedia.org/wiki/Brands_Hatch' where name = 'Brands Hatch';
update public.track_venues set kind = 'real', based_on = 'Circuit de Catalunya', opened_year = 1991, history = 'The circuit lies at Montmeló near Barcelona and opened in September 1991, after which it hosted the Spanish Grand Prix for many seasons. It was called simply Circuit de Catalunya until a 2013 sponsorship deal added Barcelona to the name, and its layout has been revised several times, most recently in 2021.', source_url = 'https://en.wikipedia.org/wiki/Circuit_de_Barcelona-Catalunya' where name = 'Circuit de Barcelona-Catalunya';
update public.track_venues set kind = 'real', based_on = 'Spa-Francorchamps', opened_year = 1921, history = 'Set in the Ardennes forest in Belgium, Spa began as a roughly 15 km triangular course on public roads, with the first car race held in 1922. It was cut to a permanent circuit of under 7 km in 1979, and the Raidillon de l''Eau Rouge sequence is its best-known section.', source_url = 'https://en.wikipedia.org/wiki/Circuit_de_Spa-Francorchamps' where name = 'Circuit de Spa-Francorchamps';
update public.track_venues set kind = 'real', based_on = 'Daytona International Speedway', opened_year = 1959, history = 'Located in Daytona Beach, Florida, the speedway opened in 1959 with a 2.5-mile tri-oval and has hosted the Daytona 500 since its first year. A road course through the infield is used for sports car racing such as the Rolex 24 at Daytona.', source_url = 'https://en.wikipedia.org/wiki/Daytona_International_Speedway' where name = 'Daytona Intl Speedway';
update public.track_venues set kind = 'real', based_on = null, opened_year = 1932, history = 'The circuit is near the town of Hockenheim in Baden-Württemberg, Germany, and opened in 1932 as a roughly 12 km triangular course. A 2002 redesign by Hermann Tilke shortened the Grand Prix layout to 4.574 km.', source_url = 'https://en.wikipedia.org/wiki/Hockenheimring' where name = 'Hockenheimring';
update public.track_venues set kind = 'real', based_on = null, opened_year = 1995, history = 'The speedway is in Homestead, Florida, and opened in November 1995, taking its current name in 1999. It served as the season-ending venue for NASCAR''s national series from 2002 to 2019.', source_url = 'https://en.wikipedia.org/wiki/Homestead%E2%80%93Miami_Speedway' where name = 'Homestead-Miami Speedway';
update public.track_venues set kind = 'real', based_on = 'The Brickyard', opened_year = 1909, history = 'Located in Speedway, Indiana, it opened in August 1909 and has hosted the Indianapolis 500 since 1911. Its surface was originally paved with bricks, which gave it the nickname The Brickyard, and an infield road course was added for Formula One around 2000.', source_url = 'https://en.wikipedia.org/wiki/Indianapolis_Motor_Speedway' where name = 'Indianapolis Motor Speedway';
update public.track_venues set kind = 'real', based_on = 'Kyalami', opened_year = 1961, history = 'Kyalami is in Midrand, Gauteng, just north of Johannesburg, and opened in November 1961. It hosted the South African Grand Prix as a Formula One race between 1967 and 1985 and again in 1992 and 1993.', source_url = 'https://en.wikipedia.org/wiki/Kyalami' where name = 'Kyalami Grand Prix Circuit';
update public.track_venues set kind = 'real', based_on = 'Circuit de la Sarthe', opened_year = 1923, history = 'The circuit is at Le Mans in the Sarthe department of France and opened in 1923, and it is best known as the home of the 24 Hours of Le Mans. Its layout has been modified repeatedly, including two chicanes added to the Mulsanne Straight in 1990 to limit top speeds.', source_url = 'https://en.wikipedia.org/wiki/Circuit_de_la_Sarthe' where name = 'Le Mans - Circuit International de la Sarthe';
update public.track_venues set kind = 'real', based_on = null, opened_year = 1957, history = 'Lime Rock Park is a road course in Lakeville, in the northwest corner of Connecticut, that opened in April 1957. It has no grandstands, so spectators watch from grassy hillsides, and the track does not race on Sundays.', source_url = 'https://en.wikipedia.org/wiki/Lime_Rock_Park' where name = 'Lime Rock Park';
update public.track_venues set kind = 'real', based_on = 'Road Atlanta', opened_year = 1970, history = 'Road Atlanta is a 12-turn road course in Hall County, Georgia, just north of Braselton, and its first race was held in September 1970. It was built in about six months to replace a Can-Am race that had been cancelled after flood damage.', source_url = 'https://en.wikipedia.org/wiki/Road_Atlanta' where name = 'Michelin Raceway Road Atlanta';
update public.track_venues set kind = 'real', based_on = 'Mid-Ohio', opened_year = 1962, history = 'Mid-Ohio is a road course in Morrow County, Ohio, near Lexington and roughly between Columbus and Cleveland, that opened in 1962. A 1990 refurbishment added a second, shorter layout alongside the original.', source_url = 'https://en.wikipedia.org/wiki/Mid-Ohio_Sports_Car_Course' where name = 'Mid-Ohio Sports Car Course';
update public.track_venues set kind = 'real', based_on = 'Mount Panorama / Wahluu', opened_year = 1938, history = 'Mount Panorama is a public road circuit in Bathurst, New South Wales, that opened in March 1938 and is officially dual-named Mt Panorama/Wahluu. It drops 174 m between its highest and lowest points, and The Chase was added to Conrod Straight in 1987.', source_url = 'https://en.wikipedia.org/wiki/Mount_Panorama_Circuit' where name = 'Mount Panorama Circuit';
update public.track_venues set kind = 'real', based_on = 'Autodromo Internazionale del Mugello', opened_year = 1974, history = 'Mugello is a 15-turn permanent circuit at Scarperia e San Piero near Florence in Tuscany, opened in June 1974. It replaced a public-road course used for racing since the 1920s.', source_url = 'https://en.wikipedia.org/wiki/Mugello_Circuit' where name = 'Mugello Circuit';
update public.track_venues set kind = 'real', based_on = 'Green Hell (Nordschleife)', opened_year = 1927, history = 'The Nürburgring is a racing complex in the Eifel mountains of Rhineland-Palatinate, Germany, completed in spring 1927. Its roughly 20.8 km Nordschleife, nicknamed the Green Hell by Jackie Stewart, hosted its last Formula One race in 1976.', source_url = 'https://en.wikipedia.org/wiki/N%C3%BCrburgring' where name = 'Nürburgring';
update public.track_venues set kind = 'real', based_on = 'Elkhart Lake''s Road America', opened_year = 1955, history = 'Road America is a 14-turn road course near Elkhart Lake in Sheboygan County, Wisconsin, whose first event was held in September 1955. It was founded as a private circuit after authorities ended speed contests on public roads.', source_url = 'https://en.wikipedia.org/wiki/Road_America' where name = 'Road America';
update public.track_venues set kind = 'real', based_on = 'Sebring Raceway', opened_year = 1950, history = 'Sebring is a road course in Highlands County, Florida, built on the site of the former Hendricks Army Airfield, with its first race held on New Year''s Eve 1950. It still uses sections of the old runways and service roads, and hosted the first 12 Hours of Sebring in 1952.', source_url = 'https://en.wikipedia.org/wiki/Sebring_International_Raceway' where name = 'Sebring International Raceway';
update public.track_venues set kind = 'real', based_on = 'Silverstone Circuit', opened_year = 1948, history = 'Silverstone is a circuit on the Northamptonshire and Buckinghamshire border in England, built on a former RAF bomber station whose runways lie within the present track outline. A 1990 to 1991 redesign made it more technical, adding the twisty Luffield infield section.', source_url = 'https://en.wikipedia.org/wiki/Silverstone_Circuit' where name = 'Silverstone Racing Circuit';
update public.track_venues set kind = 'real', based_on = 'Suzuka International Racing Course', opened_year = 1962, history = 'Suzuka is a circuit in Suzuka City, Mie Prefecture, Japan, opened in September 1962. Its figure-of-eight layout, where the back straight crosses the front section on an overpass, is unique among FIA Grade 1 circuits.', source_url = 'https://en.wikipedia.org/wiki/Suzuka_Circuit' where name = 'Suzuka Circuit';
update public.track_venues set kind = 'real', based_on = null, opened_year = 1957, history = 'VIR is a road course in Alton, Virginia that first opened in August 1957, closed in 1974 and reopened in 2000. Its Full Course is about 3.27 miles with 17 turns, and its Roller Coaster section is often compared to the Corkscrew at Laguna Seca.', source_url = 'https://en.wikipedia.org/wiki/Virginia_International_Raceway' where name = 'Virginia International Raceway';
update public.track_venues set kind = 'real', based_on = 'The Glen', opened_year = 1956, history = 'The circuit sits just southwest of the village of Watkins Glen, New York, at the southern end of Seneca Lake; it opened as a permanent track in 1956 after earlier races on village streets from 1948. It hosted the Formula One United States Grand Prix for 20 straight years from 1961 to 1980.', source_url = 'https://en.wikipedia.org/wiki/Watkins_Glen_International' where name = 'Watkins Glen International Speedway';
update public.track_venues set kind = 'real', based_on = 'Laguna Seca', opened_year = 1957, history = 'Laguna Seca is a 2.238-mile, 11-turn road course in Monterey County, California, built on part of the former Fort Ord. It is best known for the steep downhill Corkscrew and has carried its current sponsor name since 2018.', source_url = 'https://en.wikipedia.org/wiki/Laguna_Seca' where name = 'WeatherTech Raceway Laguna Seca';
update public.track_venues set kind = 'real', based_on = null, opened_year = 2009, history = 'Designed by Hermann Tilke and located on Yas Island, Abu Dhabi, it opened in 2009 and has hosted the season-ending Formula One Abu Dhabi Grand Prix since that year. It runs past a marina and hotel, uses permanent lighting for night racing, and was reconfigured in 2021 to improve overtaking.', source_url = 'https://en.wikipedia.org/wiki/Yas_Marina_Circuit' where name = 'Yas Marina Circuit';
update public.track_venues set kind = 'fictional', based_on = null, opened_year = null, history = 'A fictional short-track oval of almost exactly one mile, with two short straights and two banked corners. It is one of the new locations that debuted in Forza Motorsport (2023).', source_url = 'https://gtplanet.net/forza-motorsport-2023-new-tracks-launch-20230913' where name = 'Eaglerock Speedway';
update public.track_venues set kind = 'fictional', based_on = 'Inspired by the Hakone region of Japan', opened_year = null, history = 'A fictional point-to-point mountain road of 16.5 km with 144 turns, set in the Hakone region about two hours from Tokyo. It first appeared in the original Forza Motorsport (2005) and returned to Forza Motorsport (2023) in the 20th Anniversary update.', source_url = 'https://forza.net/news/forza-motorsport-fujimi-kaido' where name = 'Fujimi Kaido';
update public.track_venues set kind = 'fictional', based_on = null, opened_year = null, history = 'An original, fictional road course of about 2.32 miles with seven turns and some elevation change. It debuted in Forza Motorsport (2023).', source_url = 'https://gtplanet.net/forza-motorsport-2023-new-tracks-launch-20230913' where name = 'Grand Oak Raceway';
update public.track_venues set kind = 'fictional', based_on = null, opened_year = null, history = 'An original, fictional circuit in Japan with nine turns and a length of about 2.6 miles. It debuted in Forza Motorsport (2023) and is separate from the Fujimi Kaido mountain road in the same region.', source_url = 'https://gtplanet.net/forza-motorsport-2023-new-tracks-launch-20230913' where name = 'Hakone';
update public.track_venues set kind = 'fictional', based_on = null, opened_year = null, history = 'A fictional circuit set in the woods of New England, known for its elevation changes and autumn scenery. It has appeared in several Forza Motorsport games, including Forza Motorsport (2023).', source_url = 'https://www.bsimracing.com/forza-motorsport-track-reveal-maple-valley/' where name = 'Maple Valley';
update public.track_venues set kind = 'fictional', based_on = null, opened_year = null, history = 'A fictional track set in St. Petersburg, Florida, combining a 2.44-mile tri-oval with a flat, technical infield for a 2.78-mile full circuit. Source is the fan-maintained Forza wiki.', source_url = 'https://forza.fandom.com/wiki/Sunset_Peninsula_Raceway' where name = 'Sunset Peninsula Raceway';

select name, kind, opened_year from public.track_venues where history is null order by name;
